import { useCallback, useEffect, useRef, useState } from 'react';
import confetti from 'canvas-confetti';
import './index.css';
import type { Contact, CrmData, Deal, Stage, View } from './lib/types';
import { stageOf } from './lib/types';
import { useCrm } from './lib/store';
import TopBar, { SearchPalette } from './components/TopBar';
import Pipeline from './components/Pipeline';
import Contacts, { ContactForm } from './components/Contacts';
import Tasks from './components/Tasks';
import ContactDrawer from './components/ContactDrawer';
import DealForm, { type DealDraft } from './components/DealForm';
import { Toast } from './components/ui';
import { daysUntil } from './lib/format';

type ToastState = { message: string; action?: { label: string; run: () => void } } | null;
export type OpenContact = { id: string; dealId?: string; tab?: 'actividad' | 'tareas' };

const VIEW_KEY = 'cartera:vista';
const readView = (): View => {
  try { const v = localStorage.getItem(VIEW_KEY); if (v === 'pipeline' || v === 'contactos' || v === 'tareas') return v; } catch { /* nada */ }
  return 'pipeline';
};

export default function App() {
  const crm = useCrm();
  const { data } = crm;
  const [view, setView] = useState<View>(readView);
  const [open, setOpen] = useState<OpenContact | null>(null);
  const [dealDraft, setDealDraft] = useState<DealDraft | null>(null);
  const [contactDraft, setContactDraft] = useState<{ contact?: Contact } | null>(null);
  const [searching, setSearching] = useState(false);
  const [toast, setToast] = useState<ToastState>(null);
  const timer = useRef<number>();

  useEffect(() => { try { localStorage.setItem(VIEW_KEY, view); } catch { /* nada */ } }, [view]);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const typing = /input|textarea|select/i.test((e.target as HTMLElement).tagName);
      if ((e.key === 'k' && (e.metaKey || e.ctrlKey)) || (e.key === '/' && !typing)) { e.preventDefault(); setSearching(true); }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, []);

  const notify = useCallback((message: string, action?: { label: string; run: () => void }) => {
    window.clearTimeout(timer.current);
    setToast({ message, action });
    timer.current = window.setTimeout(() => setToast(null), 4200);
  }, []);

  const withUndo = (message: string, snapshot: CrmData) => notify(message, { label: 'Deshacer', run: () => crm.replace(snapshot) });

  const move = (id: string, stage: Stage) => {
    const deal = data.deals.find(d => d.id === id);
    if (!deal || deal.stage === stage) return;
    const snapshot = data;
    crm.moveDeal(id, stage);
    if (stage === 'ganado') confetti({ particleCount: 70, spread: 60, origin: { y: 0.3 }, colors: ['#0F7C7A', '#17885C', '#F2C14E', '#8FE0D6'] });
    withUndo(`«${deal.title}» pasa a ${stageOf(stage).label}`, snapshot);
  };

  const removeDeal = (deal: Deal) => {
    const snapshot = data;
    crm.removeDeal(deal.id);
    setDealDraft(null);
    withUndo(`Oportunidad eliminada: ${deal.title}`, snapshot);
  };

  const markLost = (deal: Deal) => {
    const snapshot = data;
    crm.markLost(deal.id, !deal.lost);
    withUndo(deal.lost ? `«${deal.title}» vuelve al pipeline` : `«${deal.title}» marcada como perdida`, snapshot);
  };

  const removeContact = (c: Contact) => {
    const snapshot = data;
    crm.removeContact(c.id);
    setOpen(null);
    withUndo(`${c.name} eliminado de tus contactos`, snapshot);
  };

  const pendingToday = data.tasks.filter(t => !t.done && daysUntil(t.due) <= 0).length;

  return (
    <div className="cartera min-h-screen bg-[#EEF3F3] text-[#0E3B43]">
      <TopBar view={view} onView={setView} onSearch={() => setSearching(true)} onNewDeal={() => setDealDraft({})}
        dueCount={pendingToday} onReset={() => { const s = data; crm.reset(); withUndo('Datos de ejemplo restablecidos', s); }} />

      <main className="mx-auto w-full max-w-[1480px] px-4 pb-24 pt-5 sm:px-6 lg:pt-6">
        {view === 'pipeline' && (
          <Pipeline data={data} onOpen={d => setOpen({ id: d.contactId, dealId: d.id })} onMove={move}
            onEdit={d => setDealDraft({ deal: d })} onLost={markLost} onDelete={removeDeal} onNew={stage => setDealDraft({ stage })} />
        )}
        {view === 'contactos' && (
          <Contacts data={data} onOpen={id => setOpen({ id })} onNew={() => setContactDraft({})} />
        )}
        {view === 'tareas' && (
          <Tasks data={data} crm={crm} onOpen={(id, dealId) => setOpen({ id, dealId, tab: 'tareas' })} notify={notify} />
        )}
      </main>

      {open && data.contacts.some(c => c.id === open.id) && (
        <ContactDrawer key={open.id} data={data} crm={crm} open={open} onClose={() => setOpen(null)} onMove={move}
          onEditDeal={d => setDealDraft({ deal: d })} onNewDeal={() => setDealDraft({ contactId: open.id })}
          onEditContact={c => setContactDraft({ contact: c })} onRemoveContact={removeContact} onLost={markLost} notify={notify} />
      )}

      {dealDraft && (
        <DealForm draft={dealDraft} data={data} onClose={() => setDealDraft(null)} onDelete={removeDeal}
          onSave={(deal, newContact) => {
            const contactId = newContact ? crm.saveContact(newContact) : deal.contactId;
            crm.saveDeal({ ...deal, contactId });
            setDealDraft(null);
            notify(deal.id ? 'Cambios guardados' : `Oportunidad creada en ${stageOf(deal.stage).label}`);
            if (!deal.id && view !== 'pipeline') setView('pipeline');
          }} />
      )}

      {contactDraft && (
        <ContactForm contact={contactDraft.contact} onClose={() => setContactDraft(null)}
          onSave={c => {
            const id = crm.saveContact(c);
            setContactDraft(null);
            notify(c.id ? 'Contacto actualizado' : `${c.name} añadido a contactos`);
            if (!c.id) setOpen({ id });
          }} />
      )}

      {searching && (
        <SearchPalette data={data} onClose={() => setSearching(false)}
          onPick={hit => {
            setSearching(false);
            if (hit.kind === 'view') setView(hit.view);
            else if (hit.kind === 'new') setDealDraft({});
            else setOpen({ id: hit.contactId, dealId: hit.dealId, tab: hit.kind === 'task' ? 'tareas' : 'actividad' });
          }} />
      )}

      {toast && <Toast message={toast.message} action={toast.action} onClose={() => setToast(null)} />}
    </div>
  );
}

import { useState, type FormEvent, type ReactNode } from 'react';
import { ArrowRightLeft, CalendarClock, Check, Mail, MessageSquareText, PhoneCall, Trash2, Users } from 'lucide-react';
import clsx from 'clsx';
import type { ActivityType, Contact, CrmData } from '../lib/types';
import { ACTIVITY_LABEL } from '../lib/types';
import type { Crm } from '../lib/store';
import { ME } from '../data/seed';
import { daysUntil, dueLabel, isoDay, timeAgo } from '../lib/format';
import { Button, MemberDot, memberName } from './ui';

const ICON: Record<ActivityType, { icon: ReactNode; bg: string; fg: string }> = {
  nota: { icon: <MessageSquareText size={14} />, bg: '#F8EFD6', fg: '#7E5C08' },
  llamada: { icon: <PhoneCall size={14} />, bg: '#DDF2E8', fg: '#17694A' },
  email: { icon: <Mail size={14} />, bg: '#E1EDF8', fg: '#235E95' },
  reunion: { icon: <Users size={14} />, bg: '#EDE6F3', fg: '#5B4677' },
  etapa: { icon: <ArrowRightLeft size={14} />, bg: '#E3EFEE', fg: '#0B5F5D' },
};
const KINDS: ActivityType[] = ['nota', 'llamada', 'email', 'reunion'];

type Props = { contact: Contact; data: CrmData; crm: Crm; initialTab: 'actividad' | 'tareas'; focusDealId?: string; notify: (m: string) => void };

export default function ActivityPanel({ contact, data, crm, initialTab, focusDealId, notify }: Props) {
  const [tab, setTab] = useState(initialTab);
  const [kind, setKind] = useState<ActivityType>('nota');
  const [text, setText] = useState('');
  const [taskTitle, setTaskTitle] = useState('');
  const [taskDue, setTaskDue] = useState(isoDay(2));
  const [error, setError] = useState('');

  const deals = data.deals.filter(d => d.contactId === contact.id);
  const dealTitle = (id?: string) => deals.find(d => d.id === id)?.title;
  const activity = data.activities.filter(a => a.contactId === contact.id).sort((a, b) => b.at.localeCompare(a.at));
  const tasks = data.tasks.filter(t => t.contactId === contact.id).sort((a, b) => Number(a.done) - Number(b.done) || a.due.localeCompare(b.due));
  const pending = tasks.filter(t => !t.done).length;
  const dealId = focusDealId ?? deals.find(d => !d.lost && d.stage !== 'ganado')?.id;

  const addNote = (e: FormEvent) => {
    e.preventDefault();
    if (text.trim().length < 3) return setError('Escribe al menos unas palabras sobre lo ocurrido.');
    crm.addActivity({ contactId: contact.id, dealId, type: kind, text: text.trim() });
    setText(''); setError('');
    notify(`${ACTIVITY_LABEL[kind]} guardada en el historial`);
  };
  const addTask = (e: FormEvent) => {
    e.preventDefault();
    if (taskTitle.trim().length < 3) return setError('Describe la tarea (mínimo 3 caracteres).');
    if (!taskDue) return setError('Elige una fecha de vencimiento.');
    crm.addTask({ title: taskTitle.trim(), contactId: contact.id, dealId, due: taskDue, owner: ME });
    setTaskTitle(''); setError('');
    notify(`Tarea programada para ${dueLabel(taskDue).toLowerCase()}`);
  };

  const tabBtn = (id: 'actividad' | 'tareas', label: string, count: number) => (
    <button type="button" role="tab" aria-selected={tab === id} onClick={() => { setTab(id); setError(''); }}
      className={clsx('relative pb-2.5 text-sm font-semibold transition-colors', tab === id ? 'text-[#0E3B43]' : 'text-[#6B8488] hover:text-[#0E3B43]')}>
      {label} <span className="num ml-1 rounded-full bg-[#E3ECEC] px-1.5 text-xs">{count}</span>
      {tab === id && <span className="absolute inset-x-0 bottom-0 h-0.5 rounded-full bg-[#0F7C7A]" />}
    </button>
  );

  return (
    <section className="border-t border-[#E3ECEC] px-4 pt-4 sm:px-6">
      <div role="tablist" className="flex gap-6 border-b border-[#E3ECEC]">
        {tabBtn('actividad', 'Historial', activity.length)}
        {tabBtn('tareas', 'Tareas', pending)}
      </div>

      {tab === 'actividad' ? (
        <>
          <form onSubmit={addNote} className="mt-4 rounded-2xl border border-[#D6E2E3] bg-white p-3">
            <div className="flex flex-wrap gap-1.5" role="radiogroup" aria-label="Tipo de actividad">
              {KINDS.map(k => (
                <button key={k} type="button" role="radio" aria-checked={kind === k} onClick={() => setKind(k)}
                  className={clsx('inline-flex items-center gap-1.5 rounded-lg px-2.5 py-1 text-xs font-semibold transition-colors', kind === k ? 'bg-[#0E3B43] text-white' : 'bg-[#EEF3F3] text-[#35585E] hover:bg-[#E3ECEC]')}>
                  {ICON[k].icon}{ACTIVITY_LABEL[k]}
                </button>
              ))}
            </div>
            <textarea value={text} onChange={e => { setText(e.target.value); setError(''); }} rows={2} aria-label="Detalle de la actividad"
              placeholder={kind === 'llamada' ? '¿Qué se habló en la llamada?' : kind === 'reunion' ? 'Acuerdos y próximos pasos de la reunión' : kind === 'email' ? 'Resumen del email enviado o recibido' : `Escribe una nota sobre ${contact.name.split(' ')[0]}…`}
              className={clsx('field soft mt-2.5 resize-none', error && 'invalid')} />
            <div className="mt-2 flex items-center gap-3">
              <Button variant="primary" type="submit" className="py-1.5">Guardar en el historial</Button>
              <p className="min-w-0 flex-1 truncate text-xs text-[#B03A22]" role="alert">{error}</p>
            </div>
          </form>

          <ol className="relative mt-5 space-y-4 pb-2 before:absolute before:bottom-2 before:left-[15px] before:top-2 before:w-px before:bg-[#D6E2E3]">
            {activity.map(a => (
              <li key={a.id} className="group relative flex gap-3">
                <span className="relative z-10 flex h-8 w-8 shrink-0 items-center justify-center rounded-full ring-4 ring-[#F7FAFA]" style={{ background: ICON[a.type].bg, color: ICON[a.type].fg }} aria-hidden>{ICON[a.type].icon}</span>
                <div className="min-w-0 flex-1 pt-0.5">
                  <p className="text-xs text-[#56767B]">
                    <span className="font-semibold text-[#24494F]">{ACTIVITY_LABEL[a.type]}</span> · {memberName(a.author).split(' ')[0]} · {timeAgo(a.at)}
                    {dealTitle(a.dealId) && <> · <span className="text-[#0B5F5D]">{dealTitle(a.dealId)}</span></>}
                  </p>
                  <p className="mt-1 text-sm leading-relaxed text-[#0E3B43]">{a.text}</p>
                </div>
                <button type="button" aria-label="Borrar entrada del historial" onClick={() => crm.removeActivity(a.id)}
                  className="h-8 w-8 shrink-0 rounded-lg text-[#7D9396] opacity-0 transition-opacity hover:bg-[#FBE5DE] hover:text-[#A23A22] focus:opacity-100 group-hover:opacity-100">
                  <Trash2 size={14} className="mx-auto" />
                </button>
              </li>
            ))}
            {activity.length === 0 && <li className="py-6 text-center text-sm text-[#56767B]">Sin actividad todavía. Registra la primera llamada o nota.</li>}
          </ol>
        </>
      ) : (
        <>
          <form onSubmit={addTask} className="mt-4 flex flex-col gap-2 rounded-2xl border border-[#D6E2E3] bg-white p-3 sm:flex-row">
            <input className={clsx('field flex-1', error && 'invalid')} value={taskTitle} onChange={e => { setTaskTitle(e.target.value); setError(''); }} placeholder="Próximo paso, p. ej. Enviar presupuesto" aria-label="Nueva tarea" />
            <input type="date" className="field fit" value={taskDue} onChange={e => setTaskDue(e.target.value)} aria-label="Fecha de vencimiento" />
            <Button variant="primary" type="submit">Añadir tarea</Button>
          </form>
          {error && <p className="mt-1.5 text-xs text-[#B03A22]" role="alert">{error}</p>}
          <ul className="mt-3 space-y-1.5 pb-2">
            {tasks.map(t => {
              const n = daysUntil(t.due);
              return (
                <li key={t.id} className="group flex items-center gap-3 rounded-xl bg-white px-3 py-2.5">
                  <button type="button" role="checkbox" aria-checked={t.done} aria-label={`Completar: ${t.title}`} onClick={() => crm.toggleTask(t.id)}
                    className={clsx('flex h-5 w-5 shrink-0 items-center justify-center rounded-md border-2 transition-colors', t.done ? 'border-[#17885C] bg-[#17885C] text-white' : 'border-[#9FB7BA] hover:border-[#0F7C7A]')}>
                    {t.done && <Check size={13} strokeWidth={3} />}
                  </button>
                  <span className={clsx('min-w-0 flex-1 text-sm', t.done ? 'text-[#7D9396] line-through' : 'font-medium text-[#0E3B43]')}>{t.title}</span>
                  {!t.done && <span className={clsx('inline-flex shrink-0 items-center gap-1 text-xs font-semibold', n < 0 ? 'text-[#B03A22]' : n === 0 ? 'text-[#7E5C08]' : 'text-[#56767B]')}><CalendarClock size={13} />{dueLabel(t.due)}</span>}
                  <MemberDot id={t.owner} size={20} />
                  <button type="button" aria-label={`Borrar tarea: ${t.title}`} onClick={() => crm.removeTask(t.id)}
                    className="rounded-lg p-1.5 text-[#7D9396] opacity-0 hover:bg-[#FBE5DE] hover:text-[#A23A22] focus:opacity-100 group-hover:opacity-100"><Trash2 size={14} /></button>
                </li>
              );
            })}
            {tasks.length === 0 && <li className="py-6 text-center text-sm text-[#56767B]">No hay tareas. Programa el próximo paso para no perder el hilo.</li>}
          </ul>
        </>
      )}
    </section>
  );
}

import { Building2, CalendarDays, Ellipsis, Mail, MapPin, Pencil, Phone, Plus, RotateCcw, Trash2, X, XCircle } from 'lucide-react';
import clsx from 'clsx';
import type { OpenContact } from '../App';
import type { Contact, CrmData, Deal, Stage } from '../lib/types';
import { STAGES } from '../lib/types';
import type { Crm } from '../lib/store';
import { money, shortDate } from '../lib/format';
import { Avatar, Drawer, IconButton, MemberDot, Menu, StagePill, memberName } from './ui';
import ActivityPanel from './ActivityPanel';

type Props = {
  data: CrmData; crm: Crm; open: OpenContact; onClose: () => void;
  onMove: (id: string, stage: Stage) => void; onEditDeal: (d: Deal) => void; onNewDeal: () => void; onLost: (d: Deal) => void;
  onEditContact: (c: Contact) => void; onRemoveContact: (c: Contact) => void; notify: (m: string) => void;
};

export default function ContactDrawer({ data, crm, open, onClose, onMove, onEditDeal, onNewDeal, onLost, onEditContact, onRemoveContact, notify }: Props) {
  const c = data.contacts.find(x => x.id === open.id)!;
  const rank = (d: Deal) => (d.id === open.dealId ? 0 : d.lost ? 3 : d.stage === 'ganado' ? 2 : 1);
  const deals = data.deals.filter(d => d.contactId === c.id).sort((a, b) => rank(a) - rank(b));
  const openValue = deals.filter(d => !d.lost && d.stage !== 'ganado').reduce((s, d) => s + d.value, 0);
  const wonValue = deals.filter(d => d.stage === 'ganado').reduce((s, d) => s + d.value, 0);

  return (
    <Drawer label={`Ficha de ${c.name}`} onClose={onClose}>
      <div className="flex items-center gap-2 border-b border-[#E3ECEC] bg-white px-4 py-2.5 sm:px-6">
        <p className="flex-1 text-sm font-semibold text-[#56767B]">Ficha de contacto</p>
        <Menu label="Opciones del contacto" trigger={<Ellipsis size={18} />} items={[
          { label: 'Editar contacto', icon: <Pencil size={15} />, onSelect: () => onEditContact(c) },
          { label: 'Eliminar contacto', icon: <Trash2 size={15} />, danger: true, onSelect: () => onRemoveContact(c) },
        ]} />
        <IconButton label="Cerrar ficha" onClick={onClose}><X size={19} /></IconButton>
      </div>

      <div className="flex-1 overflow-y-auto pb-20">
        <section className="bg-white px-4 pb-5 pt-5 sm:px-6">
          <div className="flex items-start gap-4">
            <Avatar contact={c} size={72} />
            <div className="min-w-0 flex-1">
              <h2 className="serif text-[26px] font-semibold leading-tight text-[#0E3B43]">{c.name}</h2>
              <p className="mt-0.5 text-sm text-[#4F6F74]">{c.role ? `${c.role} · ` : ''}<span className="font-semibold text-[#24494F]">{c.company}</span></p>
              <div className="mt-2 flex flex-wrap gap-1.5">
                {c.tags.map(t => <span key={t} className="rounded-md bg-[#E3EFEE] px-2 py-0.5 text-xs font-semibold text-[#0B5F5D]">{t}</span>)}
              </div>
            </div>
          </div>
          <div className="mt-4 flex flex-wrap gap-2">
            {c.email && <a href={`mailto:${c.email}`} className="inline-flex items-center gap-2 rounded-xl bg-[#0F7C7A] px-3.5 py-2 text-sm font-semibold text-white hover:bg-[#0B6765]"><Mail size={15} />Escribir</a>}
            {c.phone && <a href={`tel:${c.phone.replace(/\s/g, '')}`} className="inline-flex items-center gap-2 rounded-xl border border-[#CBD8DA] bg-white px-3.5 py-2 text-sm font-semibold text-[#0E3B43] hover:border-[#9FB7BA]"><Phone size={15} />Llamar</a>}
            <span className="ml-auto inline-flex items-center gap-2 text-xs font-medium text-[#56767B]"><MemberDot id={c.owner} size={22} />Lleva {memberName(c.owner).split(' ')[0]}</span>
          </div>
          <dl className="mt-5 grid grid-cols-1 gap-x-6 gap-y-2.5 rounded-2xl bg-[#F4F8F8] p-4 text-sm sm:grid-cols-2">
            {[
              { icon: <Mail size={15} />, label: 'Email', value: c.email || 'Sin email' },
              { icon: <Phone size={15} />, label: 'Teléfono', value: c.phone || 'Sin teléfono' },
              { icon: <MapPin size={15} />, label: 'Ciudad', value: c.city || 'Sin ciudad' },
              { icon: <CalendarDays size={15} />, label: 'En Cartera desde', value: shortDate(c.createdAt) },
            ].map(r => (
              <div key={r.label} className="flex min-w-0 items-center gap-2.5">
                <span className="text-[#0F7C7A]" aria-hidden>{r.icon}</span>
                <dt className="sr-only">{r.label}</dt>
                <dd className="truncate text-[#24494F]" title={r.value}>{r.value}</dd>
              </div>
            ))}
          </dl>
        </section>

        <section className="border-t border-[#E3ECEC] px-4 py-5 sm:px-6" aria-label="Oportunidades">
          <div className="flex items-center gap-3">
            <h3 className="serif text-lg font-semibold">Oportunidades</h3>
            <span className="num text-xs text-[#56767B]">{money(openValue)} abiertas · {money(wonValue)} ganadas</span>
            <span className="flex-1" />
            <button type="button" onClick={onNewDeal} className="inline-flex items-center gap-1 rounded-lg px-2 py-1 text-sm font-semibold text-[#0F7C7A] hover:bg-[#E3EFEE]"><Plus size={15} />Añadir</button>
          </div>
          {deals.length === 0 && <p className="mt-3 rounded-2xl border border-dashed border-[#C6D6D8] px-4 py-5 text-center text-sm text-[#56767B]">{c.name.split(' ')[0]} aún no tiene oportunidades. Crea una para seguirla en el pipeline.</p>}
          <ul className="mt-3 space-y-2.5">
            {deals.map(d => {
              const idx = STAGES.findIndex(s => s.id === d.stage);
              return (
                <li key={d.id} className={clsx('rounded-2xl border bg-white p-3.5', d.id === open.dealId ? 'border-[#0F7C7A] shadow-[0_0_0_3px_rgba(15,124,122,.12)]' : 'border-[#DCE6E7]', d.lost && 'opacity-75')}>
                  <div className="flex items-start gap-3">
                    <div className="min-w-0 flex-1">
                      <p className="font-semibold leading-snug text-[#0E3B43]">{d.title}</p>
                      <p className="mt-0.5 flex items-center gap-1.5 text-xs text-[#56767B]"><Building2 size={12} />{d.source} · cierre {shortDate(d.closeDate)}</p>
                    </div>
                    <div className="text-right">
                      <p className="serif num text-lg font-semibold">{money(d.value)}</p>
                      <StagePill stage={d.stage} lost={d.lost} />
                    </div>
                  </div>
                  {!d.lost && (
                    <div className="mt-3 grid grid-cols-5 gap-1" role="group" aria-label="Cambiar etapa">
                      {STAGES.map((s, i) => (
                        <button key={s.id} type="button" onClick={() => onMove(d.id, s.id)} aria-label={`Mover a ${s.label}`} aria-pressed={i === idx} title={s.label}
                          className="group flex flex-col gap-1 rounded-md pt-1 text-left">
                          <span className="h-1.5 w-full rounded-full transition-colors" style={{ background: i <= idx ? STAGES[idx].color : '#DCE6E7' }} />
                          <span className={clsx('truncate text-[10.5px] font-semibold', i === idx ? 'text-[#0E3B43]' : 'text-[#7D9396] group-hover:text-[#0E3B43]')}>{s.label}</span>
                        </button>
                      ))}
                    </div>
                  )}
                  <div className="mt-2.5 flex flex-wrap gap-1 border-t border-[#EDF2F2] pt-2">
                    <button type="button" onClick={() => onEditDeal(d)} className="inline-flex items-center gap-1.5 rounded-lg px-2 py-1 text-xs font-semibold text-[#35585E] hover:bg-[#EEF3F3]"><Pencil size={13} />Editar</button>
                    {d.stage !== 'ganado' && (
                      <button type="button" onClick={() => onLost(d)} className="inline-flex items-center gap-1.5 rounded-lg px-2 py-1 text-xs font-semibold text-[#35585E] hover:bg-[#EEF3F3]">
                        {d.lost ? <><RotateCcw size={13} />Reabrir</> : <><XCircle size={13} />Marcar perdida</>}
                      </button>
                    )}
                  </div>
                </li>
              );
            })}
          </ul>
        </section>

        <ActivityPanel contact={c} data={data} crm={crm} initialTab={open.tab ?? 'actividad'} focusDealId={open.dealId} notify={notify} />
      </div>
    </Drawer>
  );
}

import { useMemo, useState, type FormEvent } from 'react';
import { Search, UserPlus, UsersRound } from 'lucide-react';
import clsx from 'clsx';
import type { Contact, CrmData } from '../lib/types';
import { TAGS, TEAM, ME } from '../data/seed';
import { money, norm, timeAgo } from '../lib/format';
import { Avatar, Button, Empty, Field, MemberDot, Modal } from './ui';

type Sort = 'actividad' | 'nombre' | 'valor';

export default function Contacts({ data, onOpen, onNew }: { data: CrmData; onOpen: (id: string) => void; onNew: () => void }) {
  const [q, setQ] = useState('');
  const [tag, setTag] = useState<string | null>(null);
  const [sort, setSort] = useState<Sort>('actividad');

  const rows = useMemo(() => {
    const term = norm(q.trim());
    return data.contacts
      .map(c => {
        const acts = data.activities.filter(a => a.contactId === c.id);
        const last = acts.reduce((m, a) => (a.at > m ? a.at : m), '');
        const open = data.deals.filter(d => d.contactId === c.id && !d.lost && d.stage !== 'ganado');
        return { c, last, value: open.reduce((s, d) => s + d.value, 0), deals: open.length };
      })
      .filter(r => (!tag || r.c.tags.includes(tag)) && (!term || [r.c.name, r.c.company, r.c.city, r.c.email, r.c.role].some(s => norm(s).includes(term))))
      .sort((a, b) => sort === 'nombre' ? a.c.name.localeCompare(b.c.name, 'es') : sort === 'valor' ? b.value - a.value : b.last.localeCompare(a.last));
  }, [data, q, tag, sort]);

  const companies = new Set(data.contacts.map(c => c.company)).size;

  return (
    <div>
      <div className="flex flex-wrap items-end justify-between gap-4">
        <div>
          <h1 className="serif text-[28px] font-semibold leading-tight sm:text-[32px]">Contactos</h1>
          <p className="mt-1 text-sm text-[#4F6F74]">{data.contacts.length} personas en {companies} empresas</p>
        </div>
        <Button variant="primary" onClick={onNew}><UserPlus size={16} />Nuevo contacto</Button>
      </div>

      <div className="mt-5 flex flex-col gap-3 lg:flex-row lg:items-center">
        <label className="relative lg:w-80">
          <Search size={16} className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-[#6B8488]" />
          <input className="field with-icon" value={q} onChange={e => setQ(e.target.value)} placeholder="Filtrar por nombre, empresa o ciudad" aria-label="Filtrar contactos" />
        </label>
        <div className="no-bar -mx-4 flex flex-1 gap-1.5 overflow-x-auto px-4 lg:mx-0 lg:px-0" role="group" aria-label="Filtrar por etiqueta">
          {[null, ...TAGS].map(t => (
            <button key={t ?? 'todas'} type="button" aria-pressed={tag === t} onClick={() => setTag(t)}
              className={clsx('shrink-0 rounded-full px-3 py-1.5 text-sm font-semibold transition-colors', tag === t ? 'bg-[#0E3B43] text-white' : 'bg-white text-[#35585E] ring-1 ring-[#CBD8DA] hover:ring-[#9FB7BA]')}>
              {t ?? 'Todas'}
            </button>
          ))}
        </div>
        <div className="lg:w-56"><select className="field" value={sort} onChange={e => setSort(e.target.value as Sort)} aria-label="Ordenar contactos">
          <option value="actividad">Actividad más reciente</option>
          <option value="valor">Mayor pipeline abierto</option>
          <option value="nombre">Nombre (A–Z)</option>
        </select></div>
      </div>

      {rows.length === 0 ? (
        <div className="mt-6"><Empty icon={<UsersRound size={22} />} title="Ningún contacto coincide" text="Prueba con otra palabra o quita el filtro de etiqueta." action={<Button onClick={() => { setQ(''); setTag(null); }}>Quitar filtros</Button>} /></div>
      ) : (
        <div className="mt-5 overflow-hidden rounded-3xl border border-[#D6E2E3] bg-white">
          <div className="hidden grid-cols-[2.2fr_1.6fr_1.4fr_1.1fr_1fr_64px] gap-4 border-b border-[#E3ECEC] bg-[#F7FAFA] px-5 py-2.5 text-xs font-semibold text-[#56767B] md:grid">
            <span>Contacto</span><span>Empresa</span><span>Etiquetas</span><span className="text-right">Pipeline abierto</span><span>Último contacto</span><span>Lleva</span>
          </div>
          <ul>
            {rows.map(({ c, last, value, deals }) => (
              <li key={c.id} className="border-b border-[#EDF2F2] last:border-0">
                <button type="button" onClick={() => onOpen(c.id)}
                  className="grid w-full grid-cols-[auto_1fr_auto] items-center gap-x-3 gap-y-1 px-4 py-3 text-left transition-colors hover:bg-[#F4F8F8] md:grid-cols-[2.2fr_1.6fr_1.4fr_1.1fr_1fr_64px] md:gap-4 md:px-5">
                  <span className="row-span-2 flex items-center gap-3 md:row-span-1 md:min-w-0">
                    <Avatar contact={c} size={40} />
                    <span className="hidden min-w-0 md:block">
                      <span className="block truncate font-semibold text-[#0E3B43]">{c.name}</span>
                      <span className="block truncate text-xs text-[#56767B]">{c.role || 'Sin cargo'}</span>
                    </span>
                  </span>
                  <span className="min-w-0 md:hidden">
                    <span className="block truncate font-semibold text-[#0E3B43]">{c.name}</span>
                    <span className="block truncate text-xs text-[#56767B]">{c.company}</span>
                  </span>
                  <span className="hidden min-w-0 md:block">
                    <span className="block truncate text-sm font-medium text-[#24494F]">{c.company}</span>
                    <span className="block truncate text-xs text-[#6B8488]">{c.city}</span>
                  </span>
                  <span className="hidden flex-wrap gap-1 md:flex">
                    {c.tags.slice(0, 2).map(t => <span key={t} className="rounded-md bg-[#E3EFEE] px-1.5 py-0.5 text-[11px] font-semibold text-[#0B5F5D]">{t}</span>)}
                  </span>
                  <span className="text-right">
                    <span className="serif num block font-semibold text-[#0E3B43]">{value ? money(value) : '—'}</span>
                    <span className="block text-[11px] text-[#6B8488]">{deals ? `${deals} ${deals === 1 ? 'abierta' : 'abiertas'}` : 'Sin abiertas'}</span>
                  </span>
                  <span className="col-start-2 text-xs text-[#56767B] md:col-start-auto md:text-sm">{last ? timeAgo(last) : 'Sin actividad'}</span>
                  <span className="hidden md:block"><MemberDot id={c.owner} size={26} /></span>
                </button>
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}

/* ---------- Formulario de contacto ---------- */

type ContactInput = Omit<Contact, 'id' | 'createdAt'> & { id?: string };
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

export function ContactForm({ contact, onClose, onSave }: { contact?: Contact; onClose: () => void; onSave: (c: ContactInput) => void }) {
  const [f, setF] = useState<ContactInput>(contact ?? { name: '', role: '', company: '', email: '', phone: '', city: '', tags: ['Prospecto'], owner: ME });
  const [errors, setErrors] = useState<Record<string, string>>({});
  const set = (k: 'name' | 'role' | 'company' | 'email' | 'phone' | 'city' | 'owner') => (e: { target: { value: string } }) => {
    setF(p => ({ ...p, [k]: e.target.value })); setErrors(p => ({ ...p, [k]: '' }));
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    const err: Record<string, string> = {};
    if (f.name.trim().length < 3) err.name = 'Escribe nombre y apellido.';
    if (!f.company.trim()) err.company = 'Indica la empresa u organización.';
    if (f.email && !EMAIL.test(f.email.trim())) err.email = 'Ese email no parece válido.';
    if (f.phone && f.phone.replace(/\D/g, '').length < 9) err.phone = 'El teléfono necesita al menos 9 dígitos.';
    setErrors(err);
    if (!Object.values(err).some(Boolean)) onSave({ ...f, name: f.name.trim(), company: f.company.trim(), email: f.email.trim() });
  };

  return (
    <Modal title={contact ? 'Editar contacto' : 'Nuevo contacto'} onClose={onClose}
      footer={<><Button variant="ghost" onClick={onClose}>Cancelar</Button>
        <Button variant="primary" onClick={() => (document.getElementById('contact-form') as HTMLFormElement)?.requestSubmit()}>{contact ? 'Guardar cambios' : 'Crear contacto'}</Button></>}>
      <form id="contact-form" onSubmit={submit} noValidate className="grid gap-4 sm:grid-cols-2">
        <Field label="Nombre y apellidos" error={errors.name}><input autoFocus className={clsx('field', errors.name && 'invalid')} value={f.name} onChange={set('name')} placeholder="Ana Martín" /></Field>
        <Field label="Cargo"><input className="field" value={f.role} onChange={set('role')} placeholder="Directora de marketing" /></Field>
        <Field label="Empresa" error={errors.company}><input className={clsx('field', errors.company && 'invalid')} value={f.company} onChange={set('company')} placeholder="Panadería Trigo" /></Field>
        <Field label="Ciudad"><input className="field" value={f.city} onChange={set('city')} placeholder="Valencia" /></Field>
        <Field label="Email" error={errors.email}><input type="email" className={clsx('field', errors.email && 'invalid')} value={f.email} onChange={set('email')} placeholder="ana@empresa.es" /></Field>
        <Field label="Teléfono" error={errors.phone}><input type="tel" className={clsx('field', errors.phone && 'invalid')} value={f.phone} onChange={set('phone')} placeholder="+34 600 00 00 00" /></Field>
        <div className="sm:col-span-2">
          <span className="mb-1.5 block text-sm font-semibold text-[#24494F]">Etiquetas</span>
          <div className="flex flex-wrap gap-1.5">
            {TAGS.map(t => {
              const on = f.tags.includes(t);
              return (
                <button key={t} type="button" aria-pressed={on} onClick={() => setF(p => ({ ...p, tags: on ? p.tags.filter(x => x !== t) : [...p.tags, t] }))}
                  className={clsx('rounded-lg px-2.5 py-1 text-sm font-semibold transition-colors', on ? 'bg-[#0F7C7A] text-white' : 'bg-[#EEF3F3] text-[#35585E] hover:bg-[#E3ECEC]')}>{t}</button>
              );
            })}
          </div>
        </div>
        <Field label="Responsable"><select className="field" value={f.owner} onChange={set('owner')}>{TEAM.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}</select></Field>
      </form>
    </Modal>
  );
}

import { CalendarClock, Check, Ellipsis, Pencil, Trash2, Trophy, XCircle } from 'lucide-react';
import clsx from 'clsx';
import type { Contact, Deal, Stage, Task } from '../lib/types';
import { STAGES } from '../lib/types';
import { daysUntil, dueLabel, money, shortDate, timeAgo } from '../lib/format';
import { Avatar, MemberDot, Menu, type MenuItem } from './ui';

type Props = {
  deal: Deal;
  contact?: Contact;
  nextTask?: Task;
  dragging: boolean;
  onDragStart: (id: string) => void;
  onDragEnd: () => void;
  onOpen: () => void;
  onMove: (stage: Stage) => void;
  onEdit: () => void;
  onLost: () => void;
  onDelete: () => void;
};

export default function DealCard({ deal, contact, nextTask, dragging, onDragStart, onDragEnd, onOpen, onMove, onEdit, onLost, onDelete }: Props) {
  const won = deal.stage === 'ganado';
  const closeIn = daysUntil(deal.closeDate);
  const items: MenuItem[] = [
    { heading: 'Mover a' },
    ...STAGES.map(s => ({
      label: s.label, checked: s.id === deal.stage, onSelect: () => onMove(s.id),
      icon: <span className="h-2 w-2 rounded-full" style={{ background: s.color }} />,
    })),
    'divider',
    { label: 'Editar oportunidad', icon: <Pencil size={15} />, onSelect: onEdit },
    ...(!won ? [{ label: 'Marcar como perdida', icon: <XCircle size={15} />, onSelect: onLost }] : []),
    { label: 'Eliminar', icon: <Trash2 size={15} />, onSelect: onDelete, danger: true },
  ];

  return (
    <article
      draggable
      onDragStart={e => { e.dataTransfer.setData('text/plain', deal.id); e.dataTransfer.effectAllowed = 'move'; onDragStart(deal.id); }}
      onDragEnd={onDragEnd}
      onClick={onOpen}
      className={clsx('deal group relative cursor-grab rounded-2xl border border-[#DCE6E7] bg-white p-3.5 active:cursor-grabbing', dragging && 'dragging')}
    >
      <div className="flex items-start gap-2">
        <div className="min-w-0 flex-1">
          <p className="truncate text-xs font-medium text-[#5E7B80]">{contact?.company ?? 'Sin empresa'}</p>
          <button type="button" onClick={e => { e.stopPropagation(); onOpen(); }}
            className="mt-0.5 block text-left text-[15px] font-semibold leading-snug text-[#0E3B43] hover:text-[#0F7C7A]">
            {deal.title}
          </button>
        </div>
        <Menu label={`Opciones de ${deal.title}`} trigger={<Ellipsis size={17} />} items={items} className="relative z-10 -mr-1.5 -mt-1" />
      </div>

      <div className="mt-2.5 flex items-baseline justify-between gap-2">
        <span className="serif num text-xl font-semibold text-[#0E3B43]">{money(deal.value)}</span>
        {won
          ? <span className="inline-flex items-center gap-1 text-xs font-semibold text-[#17885C]"><Trophy size={13} />{deal.wonAt ? timeAgo(deal.wonAt) : 'Ganada'}</span>
          : <span className={clsx('text-xs font-medium', closeIn < 0 ? 'text-[#B03A22]' : 'text-[#5E7B80]')} title="Fecha prevista de cierre">
              {closeIn < 0 ? `Cierre vencido · ${shortDate(deal.closeDate)}` : `Cierre ${shortDate(deal.closeDate)}`}
            </span>}
      </div>

      <div className="mt-3 flex items-center gap-2 border-t border-[#EDF2F2] pt-2.5">
        {contact && <Avatar contact={contact} size={24} />}
        <span className="min-w-0 flex-1 truncate text-xs font-medium text-[#35585E]" title={contact?.name}>{contact?.name.split(' ')[0]}</span>
        {nextTask && !won && (
          <span title={nextTask.title}
            className={clsx('inline-flex shrink-0 items-center gap-1 rounded-md px-1.5 py-0.5 text-[11px] font-semibold',
              daysUntil(nextTask.due) < 0 ? 'bg-[#FBE5DE] text-[#A23A22]' : daysUntil(nextTask.due) === 0 ? 'bg-[#F8EFD6] text-[#7E5C08]' : 'bg-[#EEF3F3] text-[#4A6A70]')}>
            <CalendarClock size={12} />{dueLabel(nextTask.due)}
          </span>
        )}
        {won && <Check size={15} className="text-[#17885C]" aria-label="Ganada" />}
        <MemberDot id={deal.owner} size={22} />
      </div>
    </article>
  );
}

import { useState, type FormEvent } from 'react';
import { Trash2, UserPlus } from 'lucide-react';
import clsx from 'clsx';
import type { Contact, CrmData, Deal, Stage } from '../lib/types';
import { STAGES } from '../lib/types';
import { SOURCES, TEAM, ME } from '../data/seed';
import { isoDay } from '../lib/format';
import { Button, Field, Modal } from './ui';

export type DealDraft = { deal?: Deal; stage?: Stage; contactId?: string };
type DealInput = Omit<Deal, 'id' | 'createdAt'> & { id?: string };
type ContactInput = Omit<Contact, 'id' | 'createdAt'>;
type Props = { draft: DealDraft; data: CrmData; onClose: () => void; onSave: (d: DealInput, c?: ContactInput) => void; onDelete: (d: Deal) => void };

const NEW = '__nuevo';
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

export default function DealForm({ draft, data, onClose, onSave, onDelete }: Props) {
  const d = draft.deal;
  const [f, setF] = useState({
    title: d?.title ?? '',
    contactId: d?.contactId ?? draft.contactId ?? '',
    value: d ? String(d.value) : '',
    stage: d?.stage ?? draft.stage ?? 'nuevo',
    closeDate: d?.closeDate ?? isoDay(30),
    owner: d?.owner ?? ME,
    source: d?.source ?? SOURCES[0],
    newName: '', newCompany: '', newEmail: '',
  });
  const [errors, setErrors] = useState<Record<string, string>>({});
  const set = (k: keyof typeof f) => (e: { target: { value: string } }) => { setF(p => ({ ...p, [k]: e.target.value })); setErrors(p => ({ ...p, [k]: '' })); };
  const isNew = f.contactId === NEW;
  const contacts = [...data.contacts].sort((a, b) => a.company.localeCompare(b.company, 'es'));

  const submit = (e: FormEvent) => {
    e.preventDefault();
    const err: Record<string, string> = {};
    const value = Number(f.value.replace(/\./g, '').replace(',', '.'));
    if (f.title.trim().length < 3) err.title = 'Describe la oportunidad en al menos 3 caracteres.';
    if (!f.contactId) err.contactId = 'Elige un contacto o crea uno nuevo.';
    if (isNew && f.newName.trim().length < 3) err.newName = 'Escribe nombre y apellido.';
    if (isNew && !f.newCompany.trim()) err.newCompany = 'Indica la empresa.';
    if (isNew && f.newEmail && !EMAIL.test(f.newEmail)) err.newEmail = 'Ese email no parece válido.';
    if (!f.value || !Number.isFinite(value) || value <= 0) err.value = 'Introduce un importe mayor que 0 €.';
    if (!f.closeDate) err.closeDate = 'Elige una fecha prevista de cierre.';
    setErrors(err);
    if (Object.values(err).some(Boolean)) return;
    const stage = f.stage as Stage;
    const deal: DealInput = {
      ...(d ?? {}), id: d?.id, title: f.title.trim(), contactId: isNew ? '' : f.contactId, value: Math.round(value), stage,
      closeDate: f.closeDate, owner: f.owner, source: f.source,
      wonAt: stage === 'ganado' ? d?.wonAt ?? new Date().toISOString() : undefined,
    };
    onSave(deal, isNew ? { name: f.newName.trim(), company: f.newCompany.trim(), email: f.newEmail.trim(), role: '', phone: '', city: '', tags: ['Prospecto'], owner: f.owner } : undefined);
  };

  return (
    <Modal title={d ? 'Editar oportunidad' : 'Nueva oportunidad'} onClose={onClose} wide
      footer={<>
        {d && <Button variant="danger" className="mr-auto" onClick={() => onDelete(d)}><Trash2 size={15} />Eliminar</Button>}
        <Button variant="ghost" onClick={onClose}>Cancelar</Button>
        <Button variant="primary" type="submit" className="min-w-[160px]" onClick={() => (document.getElementById('deal-form') as HTMLFormElement)?.requestSubmit()}>
          {d ? 'Guardar cambios' : 'Guardar oportunidad'}
        </Button>
      </>}>
      <form id="deal-form" onSubmit={submit} noValidate className="grid gap-4 sm:grid-cols-2">
        <div className="sm:col-span-2">
          <Field label="Oportunidad" error={errors.title}>
            <input className={clsx('field', errors.title && 'invalid')} value={f.title} onChange={set('title')} placeholder="p. ej. Rediseño de la tienda online" autoFocus />
          </Field>
        </div>
        <div className="sm:col-span-2">
          <Field label="Contacto" error={errors.contactId}>
            <select className={clsx('field', errors.contactId && 'invalid')} value={f.contactId} onChange={set('contactId')}>
              <option value="">Selecciona un contacto…</option>
              {contacts.map(c => <option key={c.id} value={c.id}>{c.company} — {c.name}</option>)}
              <option value={NEW}>+ Crear contacto nuevo</option>
            </select>
          </Field>
        </div>
        {isNew && (
          <div className="pop grid gap-3 rounded-2xl border border-[#D6E2E3] bg-[#F4F8F8] p-4 sm:col-span-2 sm:grid-cols-3">
            <p className="flex items-center gap-2 text-sm font-semibold text-[#0F7C7A] sm:col-span-3"><UserPlus size={16} />Contacto nuevo</p>
            <Field label="Nombre" error={errors.newName}><input className={clsx('field', errors.newName && 'invalid')} value={f.newName} onChange={set('newName')} placeholder="Ana Martín" /></Field>
            <Field label="Empresa" error={errors.newCompany}><input className={clsx('field', errors.newCompany && 'invalid')} value={f.newCompany} onChange={set('newCompany')} placeholder="Panadería Trigo" /></Field>
            <Field label="Email" error={errors.newEmail}><input className={clsx('field', errors.newEmail && 'invalid')} value={f.newEmail} onChange={set('newEmail')} placeholder="ana@empresa.es" type="email" /></Field>
          </div>
        )}
        <Field label="Importe estimado" error={errors.value} hint="Sin IVA, en euros">
          <div className="relative">
            <input className={clsx('field num with-suffix', errors.value && 'invalid')} value={f.value} onChange={set('value')} inputMode="decimal" placeholder="12000" />
            <span className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-sm font-semibold text-[#6B8488]">€</span>
          </div>
        </Field>
        <Field label="Cierre previsto" error={errors.closeDate}>
          <input type="date" className={clsx('field', errors.closeDate && 'invalid')} value={f.closeDate} onChange={set('closeDate')} />
        </Field>
        <div className="sm:col-span-2">
          <span className="mb-1.5 block text-sm font-semibold text-[#24494F]" id="stage-label">Etapa</span>
          <div role="radiogroup" aria-labelledby="stage-label" className="grid grid-cols-2 gap-1.5 sm:grid-cols-5">
            {STAGES.map(s => (
              <button key={s.id} type="button" role="radio" aria-checked={f.stage === s.id} onClick={() => setF(p => ({ ...p, stage: s.id }))}
                className={clsx('flex items-center gap-2 rounded-xl border px-3 py-2 text-sm font-semibold transition-colors',
                  f.stage === s.id ? 'border-transparent text-[#0E3B43]' : 'border-[#CBD8DA] bg-white text-[#4A6A70] hover:border-[#9FB7BA]')}
                style={f.stage === s.id ? { background: s.soft, boxShadow: `inset 0 0 0 1.5px ${s.color}` } : undefined}>
                <span className="h-2 w-2 shrink-0 rounded-full" style={{ background: s.color }} />{s.label}
              </button>
            ))}
          </div>
        </div>
        <Field label="Responsable">
          <select className="field" value={f.owner} onChange={set('owner')}>{TEAM.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}</select>
        </Field>
        <Field label="Origen">
          <select className="field" value={f.source} onChange={set('source')}>{SOURCES.map(s => <option key={s}>{s}</option>)}</select>
        </Field>
      </form>
    </Modal>
  );
}

import { useMemo, useState, type DragEvent } from 'react';
import { Plus } from 'lucide-react';
import clsx from 'clsx';
import type { CrmData, Deal, Stage } from '../lib/types';
import { STAGES } from '../lib/types';
import { TEAM } from '../data/seed';
import { daysUntil, money, moneyShort } from '../lib/format';
import DealCard from './DealCard';
import { IconButton } from './ui';

type Props = {
  data: CrmData;
  onOpen: (d: Deal) => void;
  onMove: (id: string, stage: Stage) => void;
  onEdit: (d: Deal) => void;
  onLost: (d: Deal) => void;
  onDelete: (d: Deal) => void;
  onNew: (stage: Stage) => void;
};

export default function Pipeline({ data, onOpen, onMove, onEdit, onLost, onDelete, onNew }: Props) {
  const [owner, setOwner] = useState<string | null>(null);
  const [dragId, setDragId] = useState<string | null>(null);
  const [over, setOver] = useState<Stage | null>(null);

  const deals = useMemo(() => data.deals.filter(d => !d.lost && (!owner || d.owner === owner)), [data.deals, owner]);
  const open = deals.filter(d => d.stage !== 'ganado');
  const openTotal = open.reduce((s, d) => s + d.value, 0);
  const weighted = open.reduce((s, d) => s + d.value * STAGES.find(x => x.id === d.stage)!.prob, 0);
  const wonRecent = deals.filter(d => d.stage === 'ganado' && d.wonAt && Date.now() - new Date(d.wonAt).getTime() < 30 * 86_400_000);
  const myTasks = data.tasks.filter(t => !t.done && (!owner || t.owner === owner));
  const overdue = myTasks.filter(t => daysUntil(t.due) < 0).length;
  const today = myTasks.filter(t => daysUntil(t.due) === 0).length;

  const contact = (id: string) => data.contacts.find(c => c.id === id);
  const nextTask = (dealId: string) => data.tasks.filter(t => t.dealId === dealId && !t.done).sort((a, b) => a.due.localeCompare(b.due))[0];

  const drop = (e: DragEvent, stage: Stage) => {
    e.preventDefault();
    const id = e.dataTransfer.getData('text/plain') || dragId;
    setOver(null); setDragId(null);
    if (id) onMove(id, stage);
  };

  const metrics = [
    { label: 'Pipeline abierto', value: money(openTotal), sub: `${open.length} oportunidades en curso` },
    { label: 'Previsión ponderada', value: money(weighted), sub: 'Importe × probabilidad de cada etapa' },
    { label: 'Ganado en 30 días', value: money(wonRecent.reduce((s, d) => s + d.value, 0)), sub: `${wonRecent.length} ${wonRecent.length === 1 ? 'contrato firmado' : 'contratos firmados'}` },
    { label: 'Seguimientos para hoy', value: `${today + overdue} ${today + overdue === 1 ? 'tarea' : 'tareas'}`, sub: overdue ? `${overdue} ${overdue === 1 ? 'vencida' : 'vencidas'} de días anteriores` : 'Todo al día', alert: overdue > 0 },
  ];

  return (
    <div>
      <div className="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between">
        <div>
          <h1 className="serif text-[28px] font-semibold leading-tight sm:text-[32px]">Pipeline de oportunidades</h1>
          <p className="mt-1 text-sm text-[#4F6F74]">Arrastra una tarjeta a otra etapa o usa su menú <span aria-hidden>···</span> para moverla.</p>
        </div>
        <div className="no-bar -mx-4 flex gap-1.5 overflow-x-auto px-4 sm:mx-0 sm:px-0" role="group" aria-label="Filtrar por responsable">
          {[{ id: null, name: 'Todo el equipo', color: '' }, ...TEAM].map(m => (
            <button key={m.id ?? 'all'} type="button" aria-pressed={owner === m.id} onClick={() => setOwner(m.id)}
              className={clsx('inline-flex shrink-0 items-center gap-2 rounded-full border px-3 py-1.5 text-sm font-semibold transition-colors',
                owner === m.id ? 'border-[#0E3B43] bg-[#0E3B43] text-white' : 'border-[#CBD8DA] bg-white text-[#24494F] hover:border-[#9FB7BA]')}>
              {m.id && <span className="h-2.5 w-2.5 rounded-full" style={{ background: m.color }} />}
              {m.id ? m.name.split(' ')[0] : m.name}
            </button>
          ))}
        </div>
      </div>

      <section aria-label="Resumen del pipeline" className="mt-5 grid grid-cols-2 overflow-hidden rounded-3xl border border-[#D6E2E3] bg-white lg:grid-cols-4">
        {metrics.map((m, i) => (
          <div key={m.label} className={clsx('px-4 py-3.5 sm:px-5 sm:py-4', i % 2 === 1 && 'border-l border-[#E3ECEC]', i > 1 && 'border-t border-[#E3ECEC] lg:border-t-0', i === 2 && 'lg:border-l')}>
            <p className="text-xs font-semibold text-[#56767B] sm:text-[13px]">{m.label}</p>
            <p className={clsx('serif num mt-1 text-xl font-semibold sm:text-2xl', m.alert ? 'text-[#B03A22]' : 'text-[#0E3B43]')}>{m.value}</p>
            <p className={clsx('mt-0.5 text-xs leading-snug', m.alert ? 'font-medium text-[#B03A22]' : 'text-[#6B8488]')}>{m.sub}</p>
          </div>
        ))}
      </section>

      <div className="scroll-x -mx-4 mt-5 flex snap-x gap-3 overflow-x-auto px-4 pb-3 sm:-mx-6 sm:px-6 xl:mx-0 xl:grid xl:grid-cols-5 xl:overflow-visible xl:px-0">
        {STAGES.map(s => {
          const list = deals.filter(d => d.stage === s.id);
          const total = list.reduce((a, d) => a + d.value, 0);
          const isOver = over === s.id && dragId !== null && data.deals.find(d => d.id === dragId)?.stage !== s.id;
          return (
            <section key={s.id} aria-label={`${s.label}: ${list.length} oportunidades, ${money(total)}`}
              onDragOver={e => { if (!dragId) return; e.preventDefault(); e.dataTransfer.dropEffect = 'move'; if (over !== s.id) setOver(s.id); }}
              onDragLeave={e => { if (!e.currentTarget.contains(e.relatedTarget as Node)) setOver(null); }}
              onDrop={e => drop(e, s.id)}
              className={clsx('col-drop flex w-[82vw] max-w-[300px] shrink-0 snap-start flex-col rounded-3xl p-2 sm:w-[286px] xl:w-auto xl:max-w-none', !isOver && 'bg-[#E2EBEB]')}
              style={isOver ? { background: s.soft, boxShadow: `inset 0 0 0 2px ${s.color}` } : undefined}>
              <header className="px-2 pb-3 pt-1.5">
                <div className="flex items-center gap-2">
                  <span className="h-2.5 w-2.5 shrink-0 rounded-full" style={{ background: s.color }} />
                  <h2 className="text-sm font-bold text-[#0E3B43]">{s.label}</h2>
                  <span className="num rounded-full bg-white/80 px-2 text-xs font-semibold leading-5 text-[#4A6A70]">{list.length}</span>
                  <span className="flex-1" />
                  <IconButton label={`Añadir oportunidad en ${s.label}`} onClick={() => onNew(s.id)} className="h-8 w-8 hover:bg-white"><Plus size={16} /></IconButton>
                </div>
                <div className="mt-1 flex items-baseline justify-between gap-2">
                  <span className="serif num text-lg font-semibold text-[#0E3B43]">{moneyShort(total)}</span>
                  <span className="text-[11px] font-medium text-[#56767B]">{s.id === 'ganado' ? 'Cerrado' : `Prob. ${Math.round(s.prob * 100)} %`}</span>
                </div>
                <div className="mt-2 h-1 overflow-hidden rounded-full bg-white/70">
                  <div className="grow h-full rounded-full" style={{ width: `${Math.max(4, (total / Math.max(1, ...STAGES.map(x => deals.filter(d => d.stage === x.id).reduce((a, d) => a + d.value, 0)))) * 100)}%`, background: s.color }} />
                </div>
              </header>
              <div className="flex flex-1 flex-col gap-2">
                {list.map(d => (
                  <DealCard key={d.id} deal={d} contact={contact(d.contactId)} nextTask={nextTask(d.id)} dragging={dragId === d.id}
                    onDragStart={setDragId} onDragEnd={() => { setDragId(null); setOver(null); }}
                    onOpen={() => onOpen(d)} onMove={st => onMove(d.id, st)} onEdit={() => onEdit(d)} onLost={() => onLost(d)} onDelete={() => onDelete(d)} />
                ))}
                {list.length === 0 && (
                  <button type="button" onClick={() => onNew(s.id)}
                    className="flex min-h-[96px] flex-1 flex-col items-center justify-center rounded-2xl border border-dashed border-[#AFC4C6] px-4 text-center text-sm text-[#56767B] hover:bg-white/60">
                    {dragId ? 'Suelta aquí la oportunidad' : <>Sin oportunidades<span className="mt-0.5 text-xs font-semibold text-[#0F7C7A]">Añadir una</span></>}
                  </button>
                )}
              </div>
            </section>
          );
        })}
      </div>
    </div>
  );
}

import { useMemo, useState, type FormEvent } from 'react';
import { CalendarClock, CalendarPlus, Check, PartyPopper, Trash2 } from 'lucide-react';
import clsx from 'clsx';
import type { CrmData, Task } from '../lib/types';
import type { Crm } from '../lib/store';
import { TEAM, ME } from '../data/seed';
import { daysUntil, dueLabel, isoDay, shortDate } from '../lib/format';
import { Avatar, Button, Empty, Field, MemberDot, Modal } from './ui';

type Props = { data: CrmData; crm: Crm; onOpen: (contactId: string, dealId?: string) => void; notify: (m: string) => void };

const GROUPS = [
  { id: 'vencidas', label: 'Vencidas', test: (n: number) => n < 0, color: '#B03A22' },
  { id: 'hoy', label: 'Hoy', test: (n: number) => n === 0, color: '#7E5C08' },
  { id: 'semana', label: 'Próximos 7 días', test: (n: number) => n > 0 && n <= 7, color: '#0B5F5D' },
  { id: 'luego', label: 'Más adelante', test: (n: number) => n > 7, color: '#4A6A70' },
];

export default function Tasks({ data, crm, onOpen, notify }: Props) {
  const [done, setDone] = useState(false);
  const [owner, setOwner] = useState<string | null>(null);
  const [creating, setCreating] = useState(false);
  const [hover, setHover] = useState<number | null>(null);

  const scoped = data.tasks.filter(t => !owner || t.owner === owner);
  const list = scoped.filter(t => t.done === done).sort((a, b) => (done ? b.due.localeCompare(a.due) : a.due.localeCompare(b.due)));
  const pending = scoped.filter(t => !t.done);
  const overdue = pending.filter(t => daysUntil(t.due) < 0).length;
  const contact = (id: string) => data.contacts.find(c => c.id === id);
  const deal = (id?: string) => data.deals.find(d => d.id === id);

  const days = useMemo(() => Array.from({ length: 14 }, (_, i) => ({ i, n: pending.filter(t => daysUntil(t.due) === i).length })), [pending]);
  const max = Math.max(3, ...days.map(d => d.n));

  const row = (t: Task) => {
    const c = contact(t.contactId); const d = deal(t.dealId); const n = daysUntil(t.due);
    return (
      <li key={t.id} className="group flex items-center gap-3 border-b border-[#EDF2F2] px-4 py-3 last:border-0 sm:px-5">
        <button type="button" role="checkbox" aria-checked={t.done} aria-label={`Completar: ${t.title}`}
          onClick={() => { crm.toggleTask(t.id); if (!t.done) notify('Tarea completada y anotada en el historial'); }}
          className={clsx('flex h-[22px] w-[22px] shrink-0 items-center justify-center rounded-lg border-2 transition-colors', t.done ? 'border-[#17885C] bg-[#17885C] text-white' : 'border-[#9FB7BA] hover:border-[#0F7C7A] hover:bg-[#E3EFEE]')}>
          {t.done && <Check size={14} strokeWidth={3} />}
        </button>
        <div className="min-w-0 flex-1">
          <p className={clsx('text-[15px] leading-snug', t.done ? 'text-[#6B8488] line-through' : 'font-semibold text-[#0E3B43]')}>{t.title}</p>
          {c && (
            <button type="button" onClick={() => onOpen(c.id, t.dealId)} className="mt-1 inline-flex max-w-full items-center gap-1.5 rounded-md text-xs text-[#4F6F74] hover:text-[#0F7C7A]">
              <Avatar contact={c} size={18} /><span className="truncate"><span className="font-semibold">{c.name}</span>{d ? ` · ${d.title}` : ` · ${c.company}`}</span>
            </button>
          )}
        </div>
        <span className={clsx('hidden shrink-0 items-center gap-1 rounded-lg px-2 py-1 text-xs font-semibold sm:inline-flex',
          t.done ? 'bg-[#EEF3F3] text-[#56767B]' : n < 0 ? 'bg-[#FBE5DE] text-[#A23A22]' : n === 0 ? 'bg-[#F8EFD6] text-[#7E5C08]' : 'bg-[#EEF3F3] text-[#35585E]')}>
          <CalendarClock size={13} />{t.done ? shortDate(t.due) : dueLabel(t.due)}
        </span>
        <MemberDot id={t.owner} size={24} />
        <button type="button" aria-label={`Borrar tarea: ${t.title}`} onClick={() => { crm.removeTask(t.id); notify('Tarea borrada'); }}
          className="rounded-lg p-1.5 text-[#7D9396] hover:bg-[#FBE5DE] hover:text-[#A23A22] sm:opacity-0 sm:focus:opacity-100 sm:group-hover:opacity-100"><Trash2 size={15} /></button>
      </li>
    );
  };

  return (
    <div>
      <div className="flex flex-wrap items-end justify-between gap-4">
        <div>
          <h1 className="serif text-[28px] font-semibold leading-tight sm:text-[32px]">Seguimiento</h1>
          <p className="mt-1 text-sm text-[#4F6F74]">{pending.length} tareas pendientes{overdue ? <> · <span className="font-semibold text-[#B03A22]">{overdue} vencidas</span></> : ''}</p>
        </div>
        <Button variant="primary" onClick={() => setCreating(true)}><CalendarPlus size={16} />Nueva tarea</Button>
      </div>

      <div className="mt-5 flex flex-wrap items-center gap-2">
        <div className="inline-flex rounded-xl bg-[#DCE6E7] p-1" role="tablist" aria-label="Estado">
          {[false, true].map(v => (
            <button key={String(v)} type="button" role="tab" aria-selected={done === v} onClick={() => setDone(v)}
              className={clsx('rounded-lg px-3.5 py-1.5 text-sm font-semibold transition-colors', done === v ? 'bg-white text-[#0E3B43] shadow-sm' : 'text-[#4A6A70] hover:text-[#0E3B43]')}>
              {v ? 'Completadas' : 'Pendientes'}
            </button>
          ))}
        </div>
        <select className="field fit" value={owner ?? ''} onChange={e => setOwner(e.target.value || null)} aria-label="Responsable">
          <option value="">Todo el equipo</option>
          {TEAM.map(m => <option key={m.id} value={m.id}>{m.id === ME ? `${m.name} (tú)` : m.name}</option>)}
        </select>
      </div>

      <div className="mt-5 grid gap-5 lg:grid-cols-[1fr_320px]">
        <div className="space-y-4">
          {list.length === 0 && <Empty icon={<PartyPopper size={22} />} title={done ? 'Aún no has completado tareas' : 'Nada pendiente'} text={done ? 'Las tareas que marques aparecerán aquí.' : 'Buen trabajo. Programa el siguiente paso desde la ficha de un contacto.'} />}
          {done
            ? list.length > 0 && <ul className="overflow-hidden rounded-3xl border border-[#D6E2E3] bg-white">{list.map(row)}</ul>
            : GROUPS.map(g => {
              const items = list.filter(t => g.test(daysUntil(t.due)));
              if (!items.length) return null;
              return (
                <section key={g.id} aria-label={g.label}>
                  <h2 className="mb-2 flex items-center gap-2 px-1 text-sm font-bold" style={{ color: g.color }}>{g.label}<span className="num rounded-full bg-white px-2 text-xs leading-5 text-[#4A6A70]">{items.length}</span></h2>
                  <ul className="overflow-hidden rounded-3xl border border-[#D6E2E3] bg-white">{items.map(row)}</ul>
                </section>
              );
            })}
        </div>

        <aside className="h-fit rounded-3xl border border-[#D6E2E3] bg-white p-5" aria-label="Carga de las próximas dos semanas">
          <h2 className="serif text-lg font-semibold">Próximas dos semanas</h2>
          <p className="mt-0.5 text-xs text-[#56767B]">Tareas pendientes por día</p>
          <svg viewBox="0 0 280 120" className="mt-4 w-full" role="img" aria-label="Gráfico de tareas por día">
            {[0, Math.ceil(max / 2), max].map(v => <line key={v} x1="0" x2="280" y1={100 - (v / max) * 84} y2={100 - (v / max) * 84} stroke="#EDF2F2" />)}
            {days.map(d => {
              const h = (d.n / max) * 84; const x = d.i * 20 + 3;
              return (
                <g key={d.i} onMouseEnter={() => setHover(d.i)} onMouseLeave={() => setHover(null)}>
                  <rect x={x - 3} y="0" width="20" height="112" fill="transparent" />
                  <rect className="grow-y" x={x} y={100 - Math.max(h, 2)} width="14" height={Math.max(h, 2)} rx="4" fill={d.i === 0 ? '#D2563A' : hover === d.i ? '#0B6765' : d.n ? '#0F7C7A' : '#DCE6E7'} style={{ transformOrigin: 'bottom', transformBox: 'fill-box' }} />
                  {hover === d.i && <text x={x + 7} y={100 - h - 6} textAnchor="middle" fontSize="11" fontWeight="700" fill="#0E3B43">{d.n}</text>}
                  {(d.i === 0 || d.i === 7 || d.i === 13) && <text x={d.i === 13 ? x + 14 : x + 7} y="116" textAnchor={d.i === 13 ? 'end' : 'middle'} fontSize="10" fill="#6B8488">{d.i === 0 ? 'Hoy' : shortDate(isoDay(d.i))}</text>}
                </g>
              );
            })}
          </svg>
          <p className="mt-2 h-4 text-xs text-[#4F6F74]">{hover !== null ? `${dueLabel(isoDay(hover))}: ${days[hover].n} ${days[hover].n === 1 ? 'tarea' : 'tareas'}` : 'Pasa el ratón por una barra para ver el detalle'}</p>
          <div className="mt-4 space-y-2.5 border-t border-[#EDF2F2] pt-4">
            {TEAM.map(m => {
              const mine = data.tasks.filter(t => !t.done && t.owner === m.id);
              const late = mine.filter(t => daysUntil(t.due) < 0).length;
              return (
                <div key={m.id} className="flex items-center gap-2.5 text-sm">
                  <MemberDot id={m.id} size={26} /><span className="flex-1 font-medium text-[#24494F]">{m.name}</span>
                  {late > 0 && <span className="text-xs font-semibold text-[#B03A22]">{late} vencida{late > 1 ? 's' : ''}</span>}
                  <span className="num w-6 text-right font-semibold">{mine.length}</span>
                </div>
              );
            })}
          </div>
        </aside>
      </div>

      {creating && <TaskForm data={data} onClose={() => setCreating(false)} onSave={t => { crm.addTask(t); setCreating(false); notify(`Tarea programada para ${dueLabel(t.due).toLowerCase()}`); }} />}
    </div>
  );
}

function TaskForm({ data, onClose, onSave }: { data: CrmData; onClose: () => void; onSave: (t: Omit<Task, 'id' | 'done'>) => void }) {
  const [f, setF] = useState({ title: '', contactId: '', due: isoDay(1), owner: ME });
  const [errors, setErrors] = useState<Record<string, string>>({});
  const submit = (e: FormEvent) => {
    e.preventDefault();
    const err: Record<string, string> = {};
    if (f.title.trim().length < 3) err.title = 'Describe la tarea en al menos 3 caracteres.';
    if (!f.contactId) err.contactId = 'Elige con quién es el seguimiento.';
    if (!f.due) err.due = 'Elige una fecha.';
    setErrors(err);
    if (Object.keys(err).length) return;
    const dealId = data.deals.find(d => d.contactId === f.contactId && !d.lost && d.stage !== 'ganado')?.id;
    onSave({ ...f, title: f.title.trim(), dealId });
  };
  return (
    <Modal title="Nueva tarea de seguimiento" onClose={onClose}
      footer={<><Button variant="ghost" onClick={onClose}>Cancelar</Button><Button variant="primary" onClick={() => (document.getElementById('task-form') as HTMLFormElement)?.requestSubmit()}>Programar tarea</Button></>}>
      <form id="task-form" onSubmit={submit} noValidate className="grid gap-4 sm:grid-cols-2">
        <div className="sm:col-span-2"><Field label="Tarea" error={errors.title}><input autoFocus className={clsx('field', errors.title && 'invalid')} value={f.title} onChange={e => setF({ ...f, title: e.target.value })} placeholder="Llamar para cerrar fechas de la sesión" /></Field></div>
        <div className="sm:col-span-2"><Field label="Contacto" error={errors.contactId}>
          <select className={clsx('field', errors.contactId && 'invalid')} value={f.contactId} onChange={e => setF({ ...f, contactId: e.target.value })}>
            <option value="">Selecciona un contacto…</option>
            {data.contacts.map(c => <option key={c.id} value={c.id}>{c.name} — {c.company}</option>)}
          </select></Field></div>
        <Field label="Vence" error={errors.due}><input type="date" className={clsx('field', errors.due && 'invalid')} value={f.due} onChange={e => setF({ ...f, due: e.target.value })} /></Field>
        <Field label="Responsable"><select className="field" value={f.owner} onChange={e => setF({ ...f, owner: e.target.value })}>{TEAM.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}</select></Field>
      </form>
    </Modal>
  );
}

import { useEffect, useMemo, useRef, useState, type KeyboardEvent as KeyEvt, type ReactNode } from 'react';
import { BriefcaseBusiness, CalendarCheck2, Columns3, CornerDownLeft, Plus, RotateCcw, Search, Users } from 'lucide-react';
import clsx from 'clsx';
import type { CrmData, View } from '../lib/types';
import { AGENCY, TEAM, ME } from '../data/seed';
import { dueLabel, money, norm } from '../lib/format';
import { Avatar, Menu, StagePill } from './ui';

const TABS: { id: View; label: string; icon: ReactNode }[] = [
  { id: 'pipeline', label: 'Pipeline', icon: <Columns3 size={16} /> },
  { id: 'contactos', label: 'Contactos', icon: <Users size={16} /> },
  { id: 'tareas', label: 'Tareas', icon: <CalendarCheck2 size={16} /> },
];

type Props = { view: View; onView: (v: View) => void; onSearch: () => void; onNewDeal: () => void; onReset: () => void; dueCount: number };

export default function TopBar({ view, onView, onSearch, onNewDeal, onReset, dueCount }: Props) {
  const me = TEAM.find(t => t.id === ME)!;
  const tab = (t: (typeof TABS)[number], mobile = false) => (
    <button key={t.id} type="button" role="tab" aria-selected={view === t.id} onClick={() => onView(t.id)}
