/* ---------- Búsqueda global (paleta) ---------- */

export type Hit =
  | { kind: 'contact'; contactId: string; dealId?: undefined }
  | { kind: 'deal'; contactId: string; dealId: string }
  | { kind: 'task'; contactId: string; dealId?: string }
  | { kind: 'view'; view: View }
  | { kind: 'new' };

type Row = { key: string; group: string; hit: Hit; icon: ReactNode; title: string; meta: ReactNode };

export function SearchPalette({ data, onClose, onPick }: { data: CrmData; onClose: () => void; onPick: (h: Hit) => void }) {
  const [q, setQ] = useState('');
  const [active, setActive] = useState(0);
  const input = useRef<HTMLInputElement>(null);
  useEffect(() => { input.current?.focus(); }, []);
  const contactOf = (id: string) => data.contacts.find(c => c.id === id);

  const rows = useMemo<Row[]>(() => {
    const term = norm(q.trim());
    if (!term) {
      const last = new Map<string, string>();
      data.activities.forEach(a => { if (!last.has(a.contactId) || last.get(a.contactId)! < a.at) last.set(a.contactId, a.at); });
      const recent = [...data.contacts].sort((a, b) => (last.get(b.id) ?? '').localeCompare(last.get(a.id) ?? '')).slice(0, 4);
      return [
        { key: 'new', group: 'Acciones rápidas', hit: { kind: 'new' }, icon: <Plus size={16} />, title: 'Crear oportunidad', meta: 'Abre el formulario' },
        { key: 'vc', group: 'Acciones rápidas', hit: { kind: 'view', view: 'contactos' }, icon: <Users size={16} />, title: 'Ver todos los contactos', meta: `${data.contacts.length} contactos` },
        { key: 'vt', group: 'Acciones rápidas', hit: { kind: 'view', view: 'tareas' }, icon: <CalendarCheck2 size={16} />, title: 'Ver tareas de seguimiento', meta: `${data.tasks.filter(t => !t.done).length} pendientes` },
        ...recent.map(c => ({ key: c.id, group: 'Actividad reciente', hit: { kind: 'contact', contactId: c.id } as Hit, icon: <Avatar contact={c} size={28} />, title: c.name, meta: c.company })),
      ];
    }
    const has = (...s: string[]) => s.some(x => norm(x).includes(term));
    const contacts = data.contacts.filter(c => has(c.name, c.company, c.email, c.role, c.city)).slice(0, 5)
      .map(c => ({ key: c.id, group: 'Contactos', hit: { kind: 'contact', contactId: c.id } as Hit, icon: <Avatar contact={c} size={28} />, title: c.name, meta: `${c.role} · ${c.company}` }));
    const deals = data.deals.filter(d => has(d.title, contactOf(d.contactId)?.company ?? '')).slice(0, 5)
      .map(d => ({ key: d.id, group: 'Oportunidades', hit: { kind: 'deal', contactId: d.contactId, dealId: d.id } as Hit, icon: <Columns3 size={16} />, title: d.title,
        meta: <span className="flex items-center gap-2"><StagePill stage={d.stage} lost={d.lost} /><span className="num">{money(d.value)}</span></span> }));
    const tasks = data.tasks.filter(t => has(t.title)).slice(0, 4)
      .map(t => ({ key: t.id, group: 'Tareas', hit: { kind: 'task', contactId: t.contactId, dealId: t.dealId } as Hit, icon: <CalendarCheck2 size={16} />, title: t.title,
        meta: `${t.done ? 'Hecha' : dueLabel(t.due)} · ${contactOf(t.contactId)?.name ?? ''}` }));
    return [...contacts, ...deals, ...tasks];
  }, [q, data]);

  useEffect(() => setActive(0), [q]);

  const onKey = (e: KeyEvt) => {
    if (e.key === 'Escape') onClose();
    else if (e.key === 'ArrowDown') { e.preventDefault(); setActive(i => Math.min(rows.length - 1, i + 1)); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); setActive(i => Math.max(0, i - 1)); }
    else if (e.key === 'Enter' && rows[active]) onPick(rows[active].hit);
  };

  return (
    <div className="fade fixed inset-0 z-50 flex items-start justify-center bg-[#0E3B43]/45 px-3 pt-[9vh]" onMouseDown={e => e.target === e.currentTarget && onClose()}>
      <div role="dialog" aria-modal="true" aria-label="Búsqueda global" onKeyDown={onKey} className="pop w-full max-w-xl overflow-hidden rounded-3xl bg-white shadow-2xl">
        <div className="flex items-center gap-3 border-b border-[#E3ECEC] px-5">
          <Search size={19} className="text-[#0F7C7A]" />
          <input ref={input} value={q} onChange={e => setQ(e.target.value)} placeholder="Busca personas, empresas, oportunidades o tareas"
            aria-label="Buscar" className="bare h-14 flex-1 bg-transparent text-[15px] text-[#0E3B43] outline-none placeholder:text-[#7D9396]" />
          <button type="button" onClick={onClose} className="rounded-lg bg-[#EEF3F3] px-2 py-1 text-xs font-semibold text-[#4A6A70] hover:bg-[#E3ECEC]">Esc</button>
        </div>
        <div className="max-h-[60vh] overflow-y-auto p-2" role="listbox" aria-label="Resultados">
          {rows.length === 0 && (
            <p className="px-4 py-10 text-center text-sm text-[#56767B]">Nada coincide con «{q}». Prueba con el nombre de la empresa o parte del email.</p>
          )}
          {rows.map((r, i) => (
            <div key={r.key}>
              {(i === 0 || rows[i - 1].group !== r.group) && <p className="px-3 pb-1 pt-3 text-xs font-semibold text-[#6B8488]">{r.group}</p>}
              <button type="button" role="option" aria-selected={i === active} onMouseEnter={() => setActive(i)} onClick={() => onPick(r.hit)}
                className={clsx('flex w-full items-center gap-3 rounded-2xl px-3 py-2.5 text-left', i === active && 'bg-[#EEF3F3]')}>
                <span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-xl bg-[#E3EFEE] text-[#0F7C7A]">{r.icon}</span>
                <span className="min-w-0 flex-1">
                  <span className="block truncate text-sm font-semibold text-[#0E3B43]">{r.title}</span>
                  <span className="block truncate text-xs text-[#56767B]">{r.meta}</span>
                </span>
                {i === active && <CornerDownLeft size={15} className="text-[#7D9396]" />}
              </button>
            </div>
          ))}
        </div>
        <div className="flex gap-4 border-t border-[#E3ECEC] bg-[#F7FAFA] px-5 py-2.5 text-xs text-[#56767B]">
          <span>↑ ↓ para moverte</span><span>Intro para abrir</span><span className="ml-auto">Pulsa / en cualquier pantalla</span>
        </div>
      </div>
    </div>
  );
}

