export type MenuItem = { label: string; onSelect: () => void; icon?: ReactNode; danger?: boolean; checked?: boolean } | 'divider' | { heading: string };

export function Menu({ label, trigger, items, align = 'right', className, triggerClass }: { label: string; trigger: ReactNode; items: MenuItem[]; align?: 'left' | 'right'; className?: string; triggerClass?: string }) {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!open) return;
    const close = (e: MouseEvent) => { if (!ref.current?.contains(e.target as Node)) setOpen(false); };
    const esc = (e: KeyboardEvent) => { if (e.key === 'Escape') setOpen(false); };
    document.addEventListener('mousedown', close);
    document.addEventListener('keydown', esc);
    ref.current?.querySelector<HTMLButtonElement>('[role=menuitem]')?.focus();
    return () => { document.removeEventListener('mousedown', close); document.removeEventListener('keydown', esc); };
  }, [open]);
  const onKey = (e: KeyEvt) => {
    if (e.key !== 'ArrowDown' && e.key !== 'ArrowUp') return;
    e.preventDefault();
    const list = Array.from(ref.current?.querySelectorAll<HTMLButtonElement>('[role=menuitem]') ?? []);
    const i = list.indexOf(document.activeElement as HTMLButtonElement);
    list[(i + (e.key === 'ArrowDown' ? 1 : list.length - 1)) % list.length]?.focus();
  };
  return (
    <div ref={ref} className={clsx('relative', className)} onKeyDown={onKey}>
      <button type="button" aria-label={label} title={label} aria-haspopup="menu" aria-expanded={open} onClick={e => { e.stopPropagation(); setOpen(o => !o); }}
        className={triggerClass ?? 'inline-flex h-8 w-8 items-center justify-center rounded-lg text-[#4A6A70] transition-colors hover:bg-[#E3ECEC] hover:text-[#0E3B43]'}>
        {trigger}
      </button>
      {open && (
        <div role="menu" className={clsx('pop absolute top-9 z-30 w-56 rounded-2xl border border-[#DCE6E7] bg-white p-1.5 shadow-xl', align === 'right' ? 'right-0' : 'left-0')}>
          {items.map((it, i) => it === 'divider'
            ? <div key={i} className="my-1 h-px bg-[#E3ECEC]" />
            : 'heading' in it
              ? <div key={i} className="px-2.5 pb-1 pt-2 text-xs font-semibold text-[#6B8488]">{it.heading}</div>
              : (
                <button key={i} type="button" role="menuitem" onClick={e => { e.stopPropagation(); setOpen(false); it.onSelect(); }}
                  className={clsx('flex w-full items-center gap-2.5 rounded-xl px-2.5 py-2 text-left text-sm font-medium focus:bg-[#EEF3F3] hover:bg-[#EEF3F3]', it.danger ? 'text-[#A23A22]' : 'text-[#0E3B43]', it.checked && 'bg-[#EEF3F3]')}>
                  {it.icon}<span className="flex-1">{it.label}</span>{it.checked && <span className="text-xs text-[#0F7C7A]">Actual</span>}
                </button>
              ))}
        </div>
      )}
    </div>
  );
}

