export function buildSeed(): CrmData {
  const contacts: Contact[] = contactRows.map(([id, name, role, company, email, phone, city, photo, tags, owner], i) => ({
    id, name, role, company, email, phone, city, photo, tags, owner, createdAt: isoAgo(40 + i * 9),
  }));
  const deals: Deal[] = dealRows.map(([id, title, contactId, value, stage, close, owner, source, wonAgo, lost], i) => ({
    id, title, contactId, value, stage, owner, source, closeDate: isoDay(close), createdAt: isoAgo(30 - i),
    ...(wonAgo !== undefined ? { wonAt: isoAgo(wonAgo) } : {}), ...(lost ? { lost } : {}),
  }));
  const activities: Activity[] = activityRows.map(([contactId, type, text, d, h, author, dealId], i) => ({
    id: `a${i}`, contactId, type, text, author, dealId, at: isoAgo(d, h),
  }));
  const tasks: Task[] = taskRows.map(([title, contactId, dealId, due, owner, done], i) => ({
    id: `t${i}`, title, contactId, dealId, due: isoDay(due), owner, done: !!done,
  }));
  return { contacts, deals, activities, tasks };
}

