const eur = new Intl.NumberFormat('es-ES', { style: 'currency', currency: 'EUR', maximumFractionDigits: 0 });

export const money = (n: number) => eur.format(Math.round(n));

/** Importe abreviado para cabeceras: 12,4 mil € */
export function moneyShort(n: number) {
  if (Math.abs(n) >= 1_000_000) return `${(n / 1_000_000).toLocaleString('es-ES', { maximumFractionDigits: 1 })} M€`;
  if (Math.abs(n) >= 10_000) return `${(n / 1000).toLocaleString('es-ES', { maximumFractionDigits: 1 })} mil €`;
  return money(n);
}

const DAY = 86_400_000;
export const startOfDay = (d: Date) => new Date(d.getFullYear(), d.getMonth(), d.getDate());

/** Fecha ISO (AAAA-MM-DD) a N días de hoy */
export function isoDay(offset = 0) {
  const d = new Date(startOfDay(new Date()).getTime() + offset * DAY);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

/** Instante ISO hace N días y H horas */
export const isoAgo = (days: number, hours = 0) => new Date(Date.now() - days * DAY - hours * 3_600_000).toISOString();

export function daysUntil(iso: string) {
  const [y, m, d] = iso.slice(0, 10).split('-').map(Number);
  return Math.round((new Date(y, m - 1, d).getTime() - startOfDay(new Date()).getTime()) / DAY);
}

export function shortDate(iso: string) {
  const [y, m, d] = iso.slice(0, 10).split('-').map(Number);
  const date = new Date(y, m - 1, d);
  const sameYear = y === new Date().getFullYear();
  return date.toLocaleDateString('es-ES', { day: 'numeric', month: 'short', ...(sameYear ? {} : { year: 'numeric' }) }).replace('.', '');
}

/** Etiqueta de vencimiento: "Hoy", "Mañana", "Hace 3 días", "En 5 días", "12 nov" */
export function dueLabel(iso: string) {
  const n = daysUntil(iso);
  if (n === 0) return 'Hoy';
  if (n === 1) return 'Mañana';
  if (n === -1) return 'Ayer';
  if (n < 0) return `Hace ${-n} días`;
  if (n < 7) return `En ${n} días`;
  return shortDate(iso);
}

/** Tiempo relativo para actividad: "hace 5 min", "hace 2 h", "ayer", "hace 4 días" */
export function timeAgo(iso: string) {
  const diff = Date.now() - new Date(iso).getTime();
  const min = Math.round(diff / 60_000);
  if (min < 1) return 'ahora mismo';
  if (min < 60) return `hace ${min} min`;
  const h = Math.round(min / 60);
  if (h < 24) return `hace ${h} h`;
  const d = Math.round(h / 24);
  if (d === 1) return 'ayer';
  if (d < 30) return `hace ${d} días`;
  return shortDate(iso);
}

export const initials = (name: string) => name.split(' ').filter(Boolean).slice(0, 2).map(w => w[0]).join('').toUpperCase();

export const uid = (p: string) => `${p}-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;

export const norm = (s: string) => s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');

import { useCallback, useEffect, useState } from 'react';
import type { Activity, Contact, CrmData, Deal, Stage, Task } from './types';
import { stageOf } from './types';
import { buildSeed, ME } from '../data/seed';
import { isoDay, uid } from './format';

const KEY = 'cartera:crm:v1';

function load(): CrmData {
  try {
    const raw = localStorage.getItem(KEY);
    if (raw) {
      const d = JSON.parse(raw) as CrmData;
      if (Array.isArray(d.contacts) && Array.isArray(d.deals)) return d;
    }
  } catch { /* sin almacenamiento */ }
  return buildSeed();
}

export function useCrm() {
  const [data, setData] = useState<CrmData>(load);

  useEffect(() => {
    try { localStorage.setItem(KEY, JSON.stringify(data)); } catch { /* sin almacenamiento */ }
  }, [data]);

  const log = (d: CrmData, a: Omit<Activity, 'id' | 'at' | 'author'>): Activity[] =>
    [{ ...a, id: uid('a'), at: new Date().toISOString(), author: ME }, ...d.activities];

  /** Mueve una oportunidad de etapa y deja constancia en el historial del contacto. */
  const moveDeal = useCallback((id: string, stage: Stage) => {
    setData(d => {
      const deal = d.deals.find(x => x.id === id);
      if (!deal || deal.stage === stage) return d;
      const moved: Deal = { ...deal, stage, lost: false, wonAt: stage === 'ganado' ? new Date().toISOString() : undefined };
      return {
        ...d,
        deals: [...d.deals.filter(x => x.id !== id), moved],
        activities: log(d, { contactId: deal.contactId, dealId: id, type: 'etapa', text: `Movida de ${stageOf(deal.stage).label} a ${stageOf(stage).label}` }),
      };
    });
  }, []);

  const saveDeal = useCallback((deal: Omit<Deal, 'id' | 'createdAt'> & { id?: string }) => {
    const id = deal.id ?? uid('d');
    setData(d => {
      if (deal.id) return { ...d, deals: d.deals.map(x => (x.id === deal.id ? { ...x, ...deal } as Deal : x)) };
      const created = { ...deal, id, createdAt: new Date().toISOString() } as Deal;
      return { ...d, deals: [...d.deals, created], activities: log(d, { contactId: deal.contactId, dealId: id, type: 'nota', text: `Oportunidad creada: ${deal.title}` }) };
    });
    return id;
  }, []);

  const markLost = useCallback((id: string, lost: boolean) => {
    setData(d => {
      const deal = d.deals.find(x => x.id === id);
      if (!deal) return d;
      return {
        ...d,
        deals: d.deals.map(x => (x.id === id ? { ...x, lost } : x)),
        activities: log(d, { contactId: deal.contactId, dealId: id, type: 'etapa', text: lost ? `Marcada como perdida: ${deal.title}` : `Reabierta: ${deal.title}` }),
      };
    });
  }, []);

  const removeDeal = useCallback((id: string) => {
    setData(d => ({ ...d, deals: d.deals.filter(x => x.id !== id), tasks: d.tasks.map(t => (t.dealId === id ? { ...t, dealId: undefined } : t)) }));
  }, []);

  const saveContact = useCallback((c: Omit<Contact, 'id' | 'createdAt'> & { id?: string }) => {
    const id = c.id ?? uid('c');
    setData(d => c.id
      ? { ...d, contacts: d.contacts.map(x => (x.id === c.id ? { ...x, ...c } as Contact : x)) }
      : { ...d, contacts: [{ ...c, id, createdAt: new Date().toISOString() } as Contact, ...d.contacts] });
    return id;
  }, []);

  const removeContact = useCallback((id: string) => {
    setData(d => ({
      contacts: d.contacts.filter(x => x.id !== id),
      deals: d.deals.filter(x => x.contactId !== id),
      activities: d.activities.filter(x => x.contactId !== id),
      tasks: d.tasks.filter(x => x.contactId !== id),
    }));
  }, []);

  const addActivity = useCallback((a: Omit<Activity, 'id' | 'at' | 'author'>) => {
    setData(d => ({ ...d, activities: log(d, a) }));
  }, []);

  const removeActivity = useCallback((id: string) => {
    setData(d => ({ ...d, activities: d.activities.filter(a => a.id !== id) }));
  }, []);

  const addTask = useCallback((t: Omit<Task, 'id' | 'done'>) => {
    setData(d => ({ ...d, tasks: [...d.tasks, { ...t, id: uid('t'), done: false }] }));
  }, []);

  const toggleTask = useCallback((id: string) => {
    setData(d => {
      const t = d.tasks.find(x => x.id === id);
      if (!t) return d;
      const done = !t.done;
      return {
        ...d,
        tasks: d.tasks.map(x => (x.id === id ? { ...x, done } : x)),
        activities: done ? log(d, { contactId: t.contactId, dealId: t.dealId, type: 'nota', text: `Tarea completada: ${t.title}` }) : d.activities,
      };
    });
  }, []);

  const removeTask = useCallback((id: string) => setData(d => ({ ...d, tasks: d.tasks.filter(x => x.id !== id) })), []);
  const reset = useCallback(() => setData(buildSeed()), []);
  /** Restaura una instantánea completa (para "Deshacer"). */
  const replace = useCallback((snapshot: CrmData) => setData(snapshot), []);

  return { data, replace, moveDeal, saveDeal, markLost, removeDeal, saveContact, removeContact, addActivity, removeActivity, addTask, toggleTask, removeTask, reset };
}

